result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/app.py", "content": """"Password reset flow, fully local.

- Passwords hashed with scrypt (random salt per password).
- Reset tokens: 32 random bytes (urlsafe), only their SHA-256 is stored.
- Tokens are single-use and expire after RESET_TTL_SECONDS.
- Clock is read through utcnow() so tests can inject time travel.
"""

import hashlib
import hmac
import secrets
import sqlite3
import time

from flask import Flask, g, jsonify, request

RESET_TTL_SECONDS = 30 * 60
SCRYPT_N = 2 ** 14
SCRYPT_R = 8
SCRYPT_P = 1


def utcnow() -> float:
    """Single source of truth for time; tests monkeypatch this."""
    return time.time()


app = Flask(__name__)
app.config["DATABASE"] = "app.db"


# ---------------------------------------------------------------- database

def get_db() -> sqlite3.Connection:
    if "db" not in g:
        g.db = sqlite3.connect(app.config["DATABASE"])
        g.db.row_factory = sqlite3.Row
    return g.db


@app.teardown_appcontext
def close_db(_exc):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db(db_path: str | None = None) -> None:
    if db_path:
        app.config["DATABASE"] = db_path
    with sqlite3.connect(app.config["DATABASE"]) as db:
        db.executescript(
            """
            CREATE TABLE IF NOT EXISTS users (
                id            INTEGER PRIMARY KEY AUTOINCREMENT,
                email         TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS reset_tokens (
                token_hash TEXT PRIMARY KEY,
                user_id    INTEGER NOT NULL REFERENCES users(id),
                created_at REAL NOT NULL,
                expires_at REAL NOT NULL,
                used       INTEGER NOT NULL DEFAULT 0
            );
            """
        )


# --------------------------------------------------------------- passwords

def hash_password(password: str) -> str:
    salt = secrets.token_bytes(16)
    digest = hashlib.scrypt(
        password.encode(), salt=salt, n=SCRYPT_N, r=SCRYPT_R, p=SCRYPT_P
    )
    return f"scrypt${SCRYPT_N}${SCRYPT_R}${SCRYPT_P}${salt.hex()}${digest.hex()}"


def verify_password(password: str, stored: str) -> bool:
    algo, n, r, p, salt_hex, digest_hex = stored.split("$")
    if algo != "scrypt":
        return False
    digest = hashlib.scrypt(
        password.encode(),
        salt=bytes.fromhex(salt_hex),
        n=int(n), r=int(r), p=int(p),
    )
    return hmac.compare_digest(digest.hex(), digest_hex)


# ----------------------------------------------------------------- helpers

def _token_digest(token: str) -> str:
    # Only store a hash of the token; a stolen DB must not yield usable tokens.
    return hashlib.sha256(token.encode()).hexdigest()


# --------------------------------------------------------------- endpoints

@app.post("/auth/register")
def register():
    data = request.get_json(force=True)
    email, password = data.get("email"), data.get("password")
    if not email or not password:
        return jsonify(error="email and password required"), 400
    try:
        with get_db() as db:
            db.execute(
                "INSERT INTO users (email, password_hash) VALUES (?, ?)",
                (email, hash_password(password)),
            )
    except sqlite3.IntegrityError:
        return jsonify(error="email already registered"), 409
    return jsonify(status="registered"), 201


@app.post("/auth/login")
def login():
    data = request.get_json(force=True)
    row = get_db().execute(
        "SELECT password_hash FROM users WHERE email = ?",
        (data.get("email"),),
    ).fetchone()
    if row is None or not verify_password(data.get("password") or "", row["password_hash"]):
        return jsonify(error="invalid credentials"), 401
    return jsonify(status="logged_in")


@app.post("/auth/forgot")
def forgot():
    """Create a single-use reset token for an existing user."""
    email = request.get_json(force=True).get("email")
    db = get_db()
    user = db.execute(
        "SELECT id FROM users WHERE email = ?", (email,)
    ).fetchone()

    # No enumeration: unknown emails get the same shape of response (no token).
    if user is None:
        return jsonify(reset_token=None)

    token = secrets.token_urlsafe(32)  # ~192 bits of entropy
    now = utcnow()
    with db:
        db.execute(
            "INSERT INTO reset_tokens (token_hash, user_id, created_at, expires_at)"
            " VALUES (?, ?, ?, ?)",
            (_token_digest(token), user["id"], now, now + RESET_TTL_SECONDS),
        )

    # No mailer in this environment: hand the token back for testability.
    return jsonify(reset_token=token)


@app.post("/auth/reset")
def reset():
    """Consume {token, new_password}; anything unusable is 410 Gone."""
    data = request.get_json(force=True)
    token, new_password = data.get("token"), data.get("new_password")
    if not token or not new_password:
        return jsonify(error="token and new_password required"), 400

    db = get_db()
    row = db.execute(
        "SELECT token_hash, user_id, expires_at, used FROM reset_tokens"
        " WHERE token_hash = ?",
        (_token_digest(token),),
    ).fetchone()

    if row is None or row["used"] or utcnow() > row["expires_at"]:
        return jsonify(error="reset token invalid, expired, or already used"), 410

    with db:
        db.execute(
            "UPDATE users SET password_hash = ? WHERE id = ?",
            (hash_password(new_password), row["user_id"]),
        )
        db.execute(
            "UPDATE reset_tokens SET used = 1 WHERE token_hash = ?",
            (row["token_hash"],),
        )
    return jsonify(status="password_reset")


if __name__ == "__main__":
    init_db()
    app.run(debug=True)
"})
