result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_auth_reset.py", "content": """"Tests for the password reset flow.

The clock is injected by monkeypatching app.utcnow — no sleeping, no flakiness.
"""

import hashlib

import pytest

import app as app_module
from app import app, init_db


@pytest.fixture()
def client(tmp_path):
    init_db(db_path=str(tmp_path / "test.db"))
    with app.test_client() as client:
        yield client


@pytest.fixture()
def fake_clock(monkeypatch):
    """Replace utcnow() with a controllable clock."""
    state = {"now": 1_000_000.0}
    monkeypatch.setattr(app_module, "utcnow", lambda: state["now"])
    return state


def _register_and_forgot(client, email="alice@example.com", password="OldPass!123"):
    assert client.post(
        "/auth/register", json={"email": email, "password": password}
    ).status_code == 201
    resp = client.post("/auth/forgot", json={"email": email})
    assert resp.status_code == 200
    token = resp.get_json()["reset_token"]
    assert token  # no mailer -> token comes back in the response
    return token


# ------------------------------------------------------------- happy path

def test_token_is_single_use_then_gone(client, fake_clock):
    token = _register_and_forgot(client)

    # First use succeeds...
    resp = client.post(
        "/auth/reset", json={"token": token, "new_password": "NewPass!456"}
    )
    assert resp.status_code == 200

    # ...second use of the SAME token is rejected with 410.
    replay = client.post(
        "/auth/reset", json={"token": token, "new_password": "Hacked!789"}
    )
    assert replay.status_code == 410

    # The replay must not have changed the password again.
    assert (
        client.post(
            "/auth/login", json={"email": "alice@example.com", "password": "NewPass!456"}
        ).status_code
        == 200
    )
    assert (
        client.post(
            "/auth/login", json={"email": "alice@example.com", "password": "Hacked!789"}
        ).status_code
        == 401
    )


def test_expired_token_gets_410(client, fake_clock):
    token = _register_and_forgot(client)

    fake_clock["now"] += 30 * 60 + 1  # just past the 30-minute TTL

    resp = client.post(
        "/auth/reset", json={"token": token, "new_password": "NewPass!456"}
    )
    assert resp.status_code == 410

    # Old password still valid — nothing was reset.
    assert (
        client.post(
            "/auth/login",
            json={"email": "alice@example.com", "password": "OldPass!123"},
        ).status_code
        == 200
    )


def test_token_valid_until_exactly_ttl(client, fake_clock):
    """Boundary: still usable at exactly 30 minutes, dead one second later."""
    token = _register_and_forgot(client)
    fake_clock["now"] += 30 * 60
    assert (
        client.post(
            "/auth/reset", json={"token": token, "new_password": "NewPass!456"}
        ).status_code
        == 200
    )


def test_new_password_logs_in_old_one_stops(client, fake_clock):
    old_pw, new_pw = "OldPass!123", "BrandNew!999"
    token = _register_and_forgot(client, password=old_pw)
    assert client.post("/auth/reset", json={"token": token, "new_password": new_pw})

    login = lambda pw: client.post(  # noqa: E731
        "/auth/login", json={"email": "alice@example.com", "password": pw}
    )
    assert login(new_pw).status_code == 200   # new password works
    assert login(old_pw).status_code == 401   # old password is dead


def test_second_reset_for_same_user_invalidates_nothing_but_works_again(client, fake_clock):
    """Requesting two tokens: both are independent; using one leaves the other valid."""
    t1 = _register_and_forgot(client)
    t2 = client.post("/auth/forgot", json={"email": "alice@example.com"}).get_json()["reset_token"]
    assert t1 != t2
    assert client.post("/auth/reset", json={"token": t2, "new_password": "NewPass!456"}).status_code == 200
    assert client.post("/auth/reset", json={"token": t1, "new_password": "Other!000"}).status_code == 200
    assert client.post("/auth/login", json={"email": "alice@example.com", "password": "Other!000"}).status_code == 200


# ------------------------------------------------------------ hardening

def test_tokens_stored_hashed_not_plaintext(client, fake_clock):
    from app import get_db  # via app context below

    token = _register_and_forgot(client)
    with app.app_context():
        rows = get_db().execute("SELECT token_hash FROM reset_tokens").fetchall()
    stored = {r["token_hash"] for r in rows}
    assert hashlib.sha256(token.encode()).hexdigest() in stored
    assert token not in stored  # raw token never hits the DB


def test_unknown_email_returns_no_token(client):
    resp = client.post("/auth/forgot", json={"email": "ghost@example.com"})
    assert resp.status_code == 200
    assert resp.get_json()["reset_token"] is None


def test_bad_or_missing_token_gets_410(client):
    assert (
        client.post(
            "/auth/reset", json={"token": "nope", "new_password": "x"}
        ).status_code
        == 410
    )
    assert (
        client.post("/auth/reset", json={"new_password": "x"}).status_code
        in (400, 410)
    )
